<script setup>
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({records:Object}); const form=ref({status:'Activa'}); const editing=ref(null); const interaction=ref({}); function save(){const url=editing.value?`/relaciones-institucionales/${editing.value}`:'/relaciones-institucionales';router[editing.value?'put':'post'](url,form.value,{onSuccess:()=>{form.value={status:'Activa'};editing.value=null}})} function edit(row){editing.value=row.id;form.value={institution_id:row.institution_id,contact_id:row.contact_id,relationship_type:row.relationship_type,influence:row.influence,channel:row.channel,status:row.status,started_at:row.started_at,next_contact_at:row.next_contact_at,poa_interest:row.poa_interest,notes:row.notes}} function log(id){router.post(`/relaciones-institucionales/${id}/interacciones`,interaction.value)} function remove(id){if(confirm('¿Eliminar relación?'))router.delete(`/relaciones-institucionales/${id}`)}
</script>
<template><Head title="Relaciones"/><AppLayout><main class="module-page"><div class="module-header"><h2>Relaciones Institucionales</h2></div><form class="module-form" @submit.prevent="save"><input v-model="form.institution_id" required placeholder="ID institución"><input v-model="form.contact_id" placeholder="ID contacto"><input v-model="form.relationship_type" placeholder="Relación"><input v-model="form.influence" placeholder="Influencia"><input v-model="form.channel" placeholder="Canal"><input v-model="form.status" required placeholder="Estado"><input v-model="form.started_at" type="date"><input v-model="form.next_contact_at" type="date"><input v-model="form.poa_interest" placeholder="Interés POA"><textarea v-model="form.notes" placeholder="Notas"/><button class="module-primary">{{editing?'Actualizar':'Guardar'}} relación</button></form><section v-for="row in records.data" :key="row.id" class="module-toolbar"><b>{{ row.institution?.name || `Institución #${row.institution_id}` }}</b><span>{{ row.relationship_type }} · {{ row.status }}</span><button class="row-action" @click="edit(row)">Editar</button><button class="row-action delete" @click="remove(row.id)">Eliminar</button><form @submit.prevent="log(row.id)"><input v-model="interaction.type" required placeholder="Tipo"><input v-model="interaction.description" required placeholder="Descripción"><input v-model="interaction.occurred_at" required type="datetime-local"><input v-model="interaction.result" placeholder="Resultado"><input v-model="interaction.next_action_at" type="date"><button class="row-action">Registrar interacción</button></form></section></main></AppLayout></template>
